local _, WFJ = ...
WFJ.Data.add("quest", {
  [89001] = { "Casa tra i pascoli", "Porta 5 Pelle di Zoccolomuschio a Berdun Birrarupe al ⟦Talrendis Point=Bivacco di Talrendis⟧, ad Azshara.", "Salve, viandante!\n\nSe cerchi un posto dove appendere il cappello, non cercare oltre: l'ostello di Berdun! La tenda è un po' in disordine al momento, ma si può rimediare.\n\nTi dico io. Se mi porti ciò che mi serve per aggiustare la tenda, ti faccio stare qui gratis. Che ne dici?\n\nMi servono delle Pelli di Zoccolomuschio. I più facili da cacciare sono appena a nord di qui, ma va bene la pelle di qualsiasi zoccolomuschio.", nil, nil, 0x92b07f24, 0x8e189fa2, 0xd9ae32b5, nil, nil, "...mm" },
  [89013] = { "Un bel ronzio", "Raccogli $N1 Miele Selvatico da un Nido di Vespe usando il Fucile a Pallini di Birrarupe.", "Che ostello è, senza qualcosa da bere?\n\nSo preparare un ottimo idromele, ma sono un po' avanti con gli anni per raccogliere il miele da me. Ci sono nidi di vespe sugli alberi a nord dell'accampamento Haldaar e a ovest di Valormok. Se vedi degli ippogrifi, sei nel posto giusto.\n\nSono bestiacce, ma il miele è come niente che tu abbia mai assaggiato. Ti presto il mio fucile a pallini per far cadere gli alveari, altrimenti non ci arrivi.", nil, nil, 0x1c810d6b, 0x3da1e6f4, 0x7a20f406, nil, nil, "...mm" },
  [89015] = { "Pesca mortale", "Porta una Bistecca di ⟦Mammoth Shark=Squalo Mammut⟧ a Berdun Birrarupe al ⟦Talrendis Point=Bivacco di Talrendis⟧, ad Azshara.", "Se ti credi un vero pescatore, qui ci sono pesci più grossi di quelli che si prendono con una canna.\n\nGli squali mammut si nascondono nelle acque più profonde delle coste settentrionale e meridionale. Nuotano lontano, proprio dove il fondale precipita nel grande oceano.\n\nSono enormi; ti consiglio di portare con te un gruppo di pescatori.\n\nUn nano come me? Preferisco la terraferma. Quegli squali mi inghiottirebbero in un boccone.\n\nSe ne vai a caccia, portami un trancio di carne. Te ne sarei molto grato.", nil, nil, 0xb3dfd878, 0x3c6a73c3, 0x18179217, nil, nil, "...mm" },
  [89037] = { "Murloc ladri", "Prendi il Cristallo della Memoria da Branchiaguzza vicino alla ⟦Tower of Eldara=Torre di Eldara⟧ e portalo a Saria Lunachiara ad Azshara.", "Sulle spiagge della penisola settentrionale, a est di qui, mi sono imbattuto nella ⟦Tower of Eldara=Torre di Eldara⟧. Mentre ispezionavo il sito, ho notato un grosso murloc arancione che brandiva una clava chiodata e portava uno strano cristallo luminoso. Data la posizione, era probabilmente il tipo di cristallo che gli Alti Nobili usavano per conservare la loro storia e i loro ricordi.\n\nDobbiamo recuperare quel cristallo, {race}. Chissà quali segreti potrebbe contenere?\n\nLa via migliore per la torre è lungo le scogliere, con la salita più vicina appena a ovest di qui.", nil, nil, 0x6e48aaeb, 0x6011f7da, 0x917279fa, nil, nil, "...mm" },
  [89038] = { "Un compito monumentale", "Cerca il Marchio della Regina tra le rovine del ⟦Ravencrest Monument=Colosso di Crinocorvo⟧ e portalo a Saria Lunachiara ad Azshara.", "Si dice che la regina Azshara abbia un tempo concesso un dono ai kaldorei della casata Crinocorvo: un emblema di grande bellezza e potere magico. Questo marchio fu donato in riconoscimento dell'incrollabile lealtà dei Crinocorvo verso la regina.\n\nIl marchio è stato visto per l'ultima volta vicino al ⟦Ravencrest Monument=Colosso di Crinocorvo⟧, in cima alle scogliere della penisola meridionale. Assicurarsi una simile reliquia sarebbe la scoperta di una vita.\n\nCome sempre, le rovine del monumento brulicano di Sferzarabbia, ma confido che ormai tu sia piuttosto abile a gestirli.", nil, nil, 0x4ac1a9f7, 0x6552fb2f, 0x3fbc7528, nil, nil, "...mm" },
  [89053] = { "La tua ricompensa finale", "Scopri che cosa Saria ha da mostrarti.", "So che inizialmente sei stat<o/a> mandat<o/a> qui in ricognizione, {name}, ma hai fatto moltissimo per il campo dell'archeologia.\n\nDi certo, dopo tutta la tua fatica, ti piacerebbe sapere quali frutti porteranno i miei studi.\n\nA tal fine, prima di tornare al tuo accampamento, vorrei mostrarti una cosa. Mi faresti questo favore?", nil, nil, 0xa81ff7ad, 0x1871f749, 0x18765a13, nil, nil, "...mm" },
  [89228] = { "Pescheria della frontiera invernale", "Pesca 10 Calamaro Invernale per Berdun Birrarupe al ⟦Talrendis Point=Bivacco di Talrendis⟧, ad Azshara.", "Ogni ostello che si rispetti deve avere qualcosa da mangiare.\n\nI calamari sono di stagione e li puoi pescare dalle coste qui ad Azshara. Io non sono mai stato un gran pescatore, ma sono un cuoco coi fiocchi!\n\nChe ne dici? Ti va un po' di pesce?\n\nSe non sei granché portat<o/a> per la pesca, prova a fare amicizia con uno che pesca! O paga per la sua merce e comprane un po'!", nil, nil, 0x3c26918f, 0xb267266a, 0xf53297d7, nil, nil, "...mm" },
  [89381] = { "Puntaspilli", "Recupera le frecce nel poligono di tiro a sud della piazza di ⟦New Avalon=Nuova Avalon⟧. Puoi ottenere frecce anche combattendo i ranger.", "Ehi! Ci vuole un bel coraggio a gironzolare per il poligono mentre ci addestriamo. Praticamente stai implorando una freccia nel ginocchio, o magari nel didietro, visto come ti trascini.\n\nMa ehi, la tua sicurezza sono affari tuoi. Visto che sembri <uno/una> che ama il rischio, perché non ci dai una mano? Raccogliere le frecce dopo ogni tornata di tiri ci ruba tempo prezioso.\n\nChe ne dici di andare a recuperarne qualcuna per me, eh?", nil, nil, 0xe16773a5, 0x704c15f3, 0x61a7db97, nil, nil, "...mm" },
  [89463] = { "Patto di riservatezza", "Fizzlefuse, a ⟦New Avalon=Nuova Avalon⟧, ti ha chiesto una penna e qualcosa per rendere più comodo il suo nascondiglio. Trovi una ⟦Classy Quill=Penna Elegante⟧ nel municipio di ⟦New Avalon=Nuova Avalon⟧, e un ⟦House Prop=Arredo per la Casa⟧ da qualche parte vicino a Scholomance o nelle ⟦Karazhan Crypts=Cripte di Karazhan⟧.", "Non sono il tipo di goblin che rivela i suoi segreti al primo avventuriero che passa, ma SONO il tipo che rivela quelli di uno gnomo! Strada facendo mi sono procurato qualche schema e sto correggendo i difetti dei loro progetti. Usano ancora le micce di sicurezza! Ci credi? MICCE DI SICUREZZA!!\n\nComunque, non vedo l'ora di mostrare i miei progressi, ma mi serve una penna per scarabocchiare tutta questa roba. E mi farebbe comodo un angolino accogliente per pensare un po'. Che ne dici?", nil, nil, 0x71d0c0b4, 0xc62fcb00, 0x395b3f3b, nil, nil, "...mm" },
  [89470] = { "Cattive notizie", "Riporta lo Zaino di Saria al comandante Cantovero al ⟦Talrendis Point=Bivacco di Talrendis⟧.", "<Con le vere intenzioni di Saria rivelate e una borsa di potenti artefatti in mano, forse ora sarebbe il momento giusto di consegnare il rapporto al comandante Cantovero.>", nil, nil, 0xc03d012c, 0xef218594, 0x4d6309d5, nil, nil, "...mm" },
})
